INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66599041', 66599041, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Perorangan Dokumen Pengelolaan Risiko, Penilaian Mandiri Maturitas Spip, Mitigasi Risiko, dan Tindak Lanjut Rekomendasi Pengawasan di Lingkungan Kementerian PPN/Bappenas', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 112500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Tujuan dari pelaksanaan pekerjaan ini adalah: 1. Memastikan pelaksanaan Penilaian Mandiri Maturitas SPIP Tahun 2026 dilaksanakan sesuai dengan ketentuan dan pedoman yang berlaku. 2. Mendukung keseragaman pemahaman dan penerapan metodologi penilaian maturitas SPIP pada seluruh unit kerja. 3. Meningkatkan kualitas pengisian instrumen penilaian dan kecukupan eviden pendukung Penilaian Mandiri Maturitas SPIP. 4. Memastikan pelaksanaan Monitoring dan Evaluasi Rencana Tindak Pengendalian (RTP) berjalan secara sistematis dan terdokumentasi. 5. Mengidentifikasi tingkat capaian, kendala, dan permasalahan dalam pelaksanaan Rencana Tindak Pengendalian. 6. Menyusun rekomendasi perbaikan pengendalian intern sebagai bahan penguatan penyelenggaraan SPIP di lingkungan Kementerian PPN/Bappenas', 'Keluaran dari kegiatan Jasa Konsultansi Perorangan ini berupa tersedianya dokumen hasil pendampingan pelaksanaan Penilaian Mandiri Maturitas SPIP Tahun 2026 yang telah direviu dan didukung oleh eviden yang memadai. Selain itu, kegiatan ini menghasilkan dokumen hasil Monitoring dan Evaluasi Rencana Tindak Pengendalian (RTP) yang memuat rekapitulasi capaian pelaksanaan, identifikasi kendala, serta analisis efektivitas tindak pengendalian yang telah dilakukan oleh unit kerja. Sebagai bagian dari keluaran kegiatan, disusun pula rekomendasi perbaikan pengendalian intern dan penguatan penyelenggaraan SPIP di lingkungan Kementerian PPN/Bappenas yang dirangkum dalam laporan akhir pelaksanaan jasa konsultansi perorangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2870213);
