INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66596542', 66596542, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Pusat Pengembangan SDM Kependudukan Pembangunan Keluarga dan Keluarga Berencana', 'TECHNICAL ASSISSTANT SEKRETARIAT INEY', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 63000000, 'March 2026', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '9 Bulan', 'Technical Assisstant sebanyak 1 orang selama 9 bulan', 'a. Membantu Penanggungjawab Kegiatan dan Koordinator Umum untuk membuat proses persiapan administrasi dan pengajuan LS Hotel dalam rangka rapat-rapat dan workshop; b. Aktif berkomunikasi dengan mitra kerja penyelenggara kegiatan; c. Membantu Penanggungjawab Kegiatan dan Koordinator Umum menyiapkan dan mendokumentasikan perjalanan dinas yang dilaksanakan; d. Mendukung administrasi dan keuangan untuk Kementerian/Lembaga lainnya; e. Membantu Penanggungjawab Kegiatan menyiapkan pelaksanaan pekerjaan secara umum sesuai jadwal; f. Aktif berkomunikasi, berkoordinasi, memperhatikan RKAKL dan plotting rencana kegiatan bersama masing-masing Penanggungjawab Kegiatan; g. Membantu Koordinator Umum menyiapkan berkas LS Honorarium Koordinator Umum dan Technical Assisstant; h. Mendukung kerja Pejabat Pembuat Komitmen untuk mempertanggungjawabkan keuangan; i. Menyelenggarakan penugasan lain yang diminta oleh Kementerian Kependudukan dan Pembangunan Keluarga/Badan Kependudukan dan Keluarga Berencana Nasional (BKKBN); j. Tugas lain sesuai tugas pokok dan fungsi Pusat Pengembangan SDM Kependudukan, Pembangunan Keluarga, dan KB; k. Mendokumentasikan dan menyimpan dokumen atau arsip kegiatan dan laporan secara baik dan teratur; l. Menyusun laporan pelaksanaan seluruh tugas secara rutin bulanan dan disampaikan kepada Kepala Pusat Pengembangan SDM Kependudukan, Pembangunan Keluarga, dan KB.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2873271);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66599366', 66599366, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Penyusunan Rancangan Strategi Transformasi Manajemen Sumber Daya Manusia (SDM) untuk Peningkatan Produktivitas Nasional Proyek SMART', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 830000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Kegiatan SMART mencakup tiga komponen utama yang saling mendukung dalam memperkuat peran ASN Perencana Pembangunan untuk mendorong peningkatan produktivitas nasional. Komponen 1 berfokus pada transformasi manajemen SDM melalui penyusunan Grand Design Pengembangan SDM ASN, penguatan tata kelola manajemen ASN, penguatan ekosistem ASN perencana, pengembangan kemitraan antara pemerintah, dunia pendidikan, dan industri, serta penyusunan desain kelembagaan dan peta jalan penguatan lembaga pengelolaan dan pengembangan SDM ASN perencana. Komponen 2 menitikberatkan pada peningkatan kapasitas ASN perencana berbasis kompetensi dan kinerja melalui transformasi sistem pengembangan kapasitas ASN perencana serta program pelatihan kritikal. Sementara itu, Komponen 3 mencakup dukungan terhadap tata kelola proyek melalui jasa konsultansi dalam manajemen proyek, keuangan, dan pengadaan, serta pelaksanaan pemantauan dan evaluasi proyek, guna memastikan efektivitas dan keberlanjutan hasil pelaksanaan SMART', '1. Memimpin Sekretariat Proyek SMART; 2. Mengkoordinasikan dan mengawasi seluruh komponen program; 3. Memberikan masukan dan rekomendasi kebijakan; serta memastikan keselarasan pelaksanaan program dengan BAPPENAS, Kementerian PANRB, dan JICA; 4. Kompetensi kunci: Leadership, koordinasi, manajemen risiko, perencanaan strategis, kepatuhan terhadap aturan JICA dan GOI', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2873272);
