INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66593159', 66593159, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA LAINNYA LAPORAN HASIL RENCANA PEMBIAYAAN ALTERNATIF SARPRAS LINGKUP PENDIDIKAN TINGGI TAHUN ANGGARAN 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 94549698, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mendukung pengumpulan, verifikasi, integrasi, dan analisis data usulan sarpras dari K/L, termasuk pemetaan kesesuaian dengan skema pembiayaan alternatif. Tenaga pengolah data ini juga diharapkan dapat berkontribusi dalam proses evaluasi pelaksanaan dan pemanfaatan proyek sarpras sehingga rekomendasi kebijakan yang disusun Bappenas semakin tepat sasaran, berbasis bukti, dan mendukung pembangunan pendidikan tinggi yang berkelanjutan.', '1. Berpendidikan minimal S1 (Sarjana) dari program studi yang relevan (Ekonomi, Perencanaan Pembangunan Wilayah dan Kota, Teknik, atau bidang lain yang terkait), dari Perguruan Tinggi berakreditasi A/unggul; 2. Memiliki pengalaman kerja minimal 2 (dua) tahun dalam analisis data, perencanaan program, evaluasi proyek, atau pengelolaan pembiayaan/infrastruktur; 3. Pengalaman bekerja di lingkungan atau instansi pemerintahan menjadi nilai tambah; 4. Mampu melakukan analisis kelayakan, analisis kebutuhan pembiayaan, dan reviu dokumen usulan proyek sarpras pendidikan tinggi. 5. Memahami dasar-dasar perencanaan dan penganggaran nasional, termasuk mekanisme pendanaan sarpras pendidikan tinggi (SBSN, Rupiah Murni, KPBU, hibah, dan skema alternatif lain), serta memiliki kemampuan untuk memahami dan mengidentifikasi isu strategis terkait RPJMN 2025–2029, renstra K/L, serta dinamika kebijakan pembangunan sarpras pendidikan tinggi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2873351);
