INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66599409', 66599409, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'BADAN PENYULUHAN DAN PENGEMBANGAN SUMBER DAYA MANUSIA PERTANIAN', 'Pengadaan Kendaraan Roda Dua untuk Penyuluh', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 250000000000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '10.000 Unit', 'Pengadaan Kendaraan Roda Dua untuk Penyuluh', 'Motor Trail dan matic, Motor Trail dipilih karena memiliki kemampuan yang lebih baik untuk melewati medan berat, seperti jalan tanah, berbatu, atau area persawahan dan perkebunan yang sulit dijangkau, sedangkan Motor Matic dipilih karena mudah dioperasikan tanpa perlu perpindahan gigi secara manual, sehingga lebih nyaman dan aman digunakan oleh penyuluh perempuan dalam menjalankan tugas harian, pemberian jenis kendaraan disesuaikan bukan berdasarkan perbedaan gender semata, tetapi berdasarkan aspek efisiensi, keselamatan, dan kesesuaian medan kerja. Dengan demikian, motor trail dan matic dipilih untuk mendukung efektivitas kerja penyuluh pertanian. 1. Kapasitas Mesin (CC) Idealnya 115–150 cc, cukup untuk daya tanjak namun tetap efisien bahan bakar dan mudah dikendalikan. 2. Tinggi dan Bobot Motor Disesuaikan dengan postur rata-rata pengguna (tidak terlalu tinggi/berat), agar aman dan nyaman. 3. Ketahanan Rangka dan Suspensi Harus memiliki suspensi depan dan belakang yang kuat untuk meredam getaran di jalan rusak. 4. Efisiensi BBM Tetap mempertimbangkan konsumsi bahan bakar yang ekonomis untuk mobilitas harian. 5. Jaminan purna jual yang tersedia diseluruh wilayah Indonesia', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2874042);
