INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605078', 66605078, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Paket Fullday Meeting dalam Kota dalam rangka Penyusunan dan Revisi Peraturan, Standar, Pedoman dan Code of Practice di Bidang Keamanan Pangan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 51188000, 'January 2026', 'APBN - PNBP (D), APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Pekerjaan ini merupakan kegiatan Perjalanan Dinas Paket Meeting Dalam Kota dalam rangka mendukung pelaksanaan Penyusunan dan Revisi Peraturan, Standar, Pedoman, dan Code of Practice di Bidang Keamanan Pangan. Kegiatan ini dilaksanakan melalui serangkaian pertemuan intensif dalam format fullday meeting yang diselenggarakan di dalam wilayah kota, dengan melibatkan para peserta dari unsur internal maupun pemangku kepentingan terkait.Pelaksanaan fullday meeting ini bertujuan untuk membahas secara mendalam materi-materi teknis yang berkaitan dengan penyusunan dan revisi regulasi di bidang keamanan pangan, sehingga dihasilkan rumusan yang komprehensif, terukur, dan dapat diimplementasikan.', 'Lingkup pekerjaan dalam paket perjalanan dinas meeting dalam kota ini mencakup: 1. Paket Fullday Meeting Dalam Kota Penyediaan paket pertemuan sehari penuh (fullday) yang diselenggarakan di hotel, gedung pertemuan, atau fasilitas rapat lainnya di dalam wilayah kota. Penyelenggaraan meeting dilaksanakan selama minimal 8 (delapan) jam dalam satu hari kegiatan. Kapasitas ruang rapat disesuaikan dengan jumlah peserta yang diundang dalam setiap sesi pertemuan. Lokasi penyelenggaraan dipilih yang strategis dan mudah dijangkau oleh seluruh peserta. Biaya paket fullday meeting mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 2. Uang Transpor Pemberian uang transpor kepada peserta yang hadir dalam rangka kegiatan fullday meeting penyusunan dan revisi peraturan, standar, pedoman, dan code of practice di bidang keamanan pangan. Besaran uang transpor mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. Pemberian uang transpor dibuktikan dengan daftar hadir dan tanda terima yang ditandatangani oleh peserta yang bersangkutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2875542);
