INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605079', 66605079, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Penyusunan dan Revisi Peraturan, Standar, Pedoman dan Code of Practice di Bidang Mutu Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 118986000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pekerjaan ini merupakan pengadaan bahan penunjang dalam rangka pelaksanaan kegiatan Penyusunan dan Revisi Peraturan, Standar, Pedoman, dan Code of Practice di Bidang Mutu Pangan Olahan. Kegiatan ini bertujuan untuk mendukung kelancaran proses penyusunan dan revisi regulasi melalui serangkaian pertemuan pembahasan teknis yang melibatkan berbagai pemangku kepentingan, baik dari unsur internal maupun eksternal yang terkait dengan mutu pangan olahan. Dalam pelaksanaannya, diperlukan penyediaan kebutuhan konsumsi berupa makan siang dan snack pertemuan guna menunjang kenyamanan dan efektivitas jalannya diskusi serta pembahasan materi teknis regulasi di bidang mutu pangan olahan. Selain itu, diperlukan pula layanan penjilidan dokumen sebagai bentuk dokumentasi resmi dari setiap tahapan pembahasan yang telah dilakukan, sehingga seluruh proses dan hasil kegiatan dapat terdokumentasi dengan baik, tertata rapi, dan dapat dipertanggungjawabkan sebagai arsip resmi kegiatan.', 'Lingkup pekerjaan dalam paket belanja bahan ini mencakup: 1. Penjilidan Penyediaan layanan penjilidan dokumen hasil pertemuan pembahasan, draft peraturan, standar, pedoman, dan code of practice di bidang mutu pangan olahan yang telah disusun maupun direvisi. 2. Makan Siang Penyediaan makan siang bagi peserta pertemuan pembahasan dalam rangka penyusunan dan revisi peraturan, standar, pedoman, dan code of practice di bidang mutu pangan olahan. Besaran biaya makan siang mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 3. Snack Pertemuan Penyediaan makanan ringan/snack bagi peserta pertemuan pembahasan sebagai penunjang kelancaran jalannya diskusi dan pembahasan teknis di bidang mutu pangan olahan. Besaran biaya snack mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2875562);
