INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605071', 66605071, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Penyusunan dan Revisi Peraturan, Standar, Pedoman dan Code of Practice di Bidang Pangan Olahan Tertentu', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 47104000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '"Pekerjaan ini merupakan pengadaan bahan penunjang dalam rangka pelaksanaan kegiatan Penyusunan dan Revisi Peraturan, Standar, Pedoman, dan Code of Practice di Bidang Pangan Olahan Tertentu. Kegiatan ini bertujuan untuk mendukung kelancaran proses penyusunan dan revisi regulasi melalui serangkaian pertemuan pembahasan teknis yang melibatkan berbagai pemangku kepentingan, baik dari unsur internal maupun eksternal. Dalam pelaksanaannya, diperlukan penyediaan kebutuhan konsumsi berupa makan siang dan snack pertemuan pembahasan guna menunjang kenyamanan dan efektivitas jalannya diskusi serta pembahasan materi teknis regulasi di bidang pangan olahan tertentu. Selain itu, diperlukan pula layanan penjilidan dokumen sebagai bentuk dokumentasi resmi dari setiap tahapan pembahasan yang telah dilakukan, sehingga seluruh proses dan hasil kegiatan dapat terdokumentasi dengan baik, tertata rapi, dan dapat dipertanggungjawabkan."', '"Lingkup pekerjaan dalam paket belanja bahan ini mencakup: 1. Makan Siang Penyediaan makan siang bagi peserta pertemuan pembahasan dalam rangka penyusunan dan revisi peraturan, standar, pedoman, dan code of practice di bidang pangan olahan tertentu. Makanan disajikan dalam kondisi bersih, higienis, dan layak konsumsi, serta memenuhi standar keamanan pangan yang berlaku. Besaran biaya makan siang mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 2. Snack Pertemuan Pembahasan Penyediaan makanan ringan/snack bagi peserta pertemuan pembahasan sebagai penunjang kelancaran jalannya diskusi dan pembahasan teknis. Besaran biaya snack mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 3. Penjilidan Penyediaan layanan penjilidan dokumen hasil pertemuan pembahasan, draft peraturan, standar, pedoman, dan code of practice di bidang pangan olahan tertentu yang telah disusun maupun direvisi. Penjilidan dilakukan terhadap seluruh dokumen yang dihasilkan dari setiap tahapan pertemuan pembahasan, termasuk notulensi, risalah rapat, dan dokumen teknis lainnya."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2875647);
