INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605082', 66605082, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Paket Pertemuan Fullday dalam rangka Penyusunan dan Revisi Peraturan, Standar, Pedoman dan Code of Practice di Bidang Pangan Olahan Tertentu', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 40950000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Pekerjaan ini merupakan kegiatan penyelenggaraan Paket Pertemuan Fullday Dalam Kota dalam rangka mendukung pelaksanaan Penyusunan dan Revisi Peraturan, Standar, Pedoman, dan Code of Practice di Bidang Pangan Olahan Tertentu. Kegiatan ini dilaksanakan melalui serangkaian pertemuan intensif dalam format fullday meeting yang diselenggarakan di dalam wilayah kota, dengan melibatkan para peserta dari unsur internal maupun pemangku kepentingan terkait di bidang pangan olahan tertentu.Pelaksanaan fullday meeting ini bertujuan untuk membahas secara mendalam materi-materi teknis yang berkaitan dengan penyusunan dan revisi regulasi di bidang pangan olahan tertentu, mencakup antara lain pembahasan substansi peraturan, harmonisasi standar, penyempurnaan pedoman teknis, serta perumusan code of practice yang sesuai dengan perkembangan ilmu pengetahuan dan kebutuhan industri pangan saat ini. Dengan format pertemuan sehari penuh, diharapkan setiap sesi pembahasan dapat berlangsung secara fokus, mendalam, dan menghasilkan rumusan yang komprehensif serta dapat diimplementasikan.', '-Penyediaan paket pertemuan sehari penuh (fullday) yang diselenggarakan di hotel, gedung pertemuan, atau fasilitas rapat lainnya di dalam wilayah kota dalam rangka pembahasan penyusunan dan revisi peraturan, standar, pedoman, dan code of practice di bidang pangan olahan tertentu. -Penyelenggaraan pertemuan dilaksanakan selama minimal 8 (delapan) jam dalam satu hari kegiatan, mulai dari sesi pembukaan hingga penutupan. -Lokasi penyelenggaraan dipilih yang strategis, representatif, dan mudah dijangkau oleh seluruh peserta dari berbagai instansi terkait. -Pelaksanaan kegiatan fullday meeting wajib didokumentasikan dalam bentuk notulensi, daftar hadir peserta, serta dokumentasi foto sebagai bagian dari pertanggungjawaban kegiatan. -Besaran biaya paket fullday meeting mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2875654);
