INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605072', 66605072, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Event Organizer Kegiatan Pemberian Reward dalam rangka Evaluasi Pelayanan Publik Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 18779000, 'September 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan ini merupakan kegiatan Event Organizer Kegiatan Pemberian Reward dalam rangka mendukung pelaksanaan Evaluasi Pelayanan Publik Direktorat Standardisasi Pangan Olahan. Kegiatan ini dilaksanakan melalui kerja sama dengan pihak ketiga yang memiliki kompetensi dan pengalaman di bidang penyelenggaraan acara (event organizer) secara profesional, guna memastikan kegiatan pemberian reward dapat terlaksana dengan lancar, tertata rapi, dan berkesan bagi seluruh peserta yang hadir.Kegiatan pemberian reward ini merupakan bentuk apresiasi dan penghargaan yang diberikan oleh Direktorat Standardisasi Pangan Olahan kepada individu atau unit kerja yang telah menunjukkan kinerja pelayanan publik terbaik selama periode evaluasi yang telah ditetapkan. Melalui penyelenggaraan kegiatan ini, diharapkan dapat tercipta budaya kerja yang berorientasi pada pelayanan prima, mendorong peningkatan motivasi dan semangat kerja seluruh pegawai, serta memperkuat komitmen Direktorat Standardisasi Pangan Olahan dalam memberikan pelayanan publik yang berkualitas, transparan, dan akuntabel kepada masyarakat dan pemangku kepentingan terkait.', 'Lingkup pekerjaan dalam paket event organizer kegiatan pemberian reward ini mencakup pendukung acara Penyediaan 1 (satu) orang Master of Ceremony (MC) yang profesional, berpengalaman, dan mampu memandu acara seremonial/formal di lingkungan instansi pemerintah. Penyediaan pengisi acara/hiburan yang sesuai dengan tema dan suasana acara pemberian reward. Penyediaan tenaga floor manager yang berpengalaman untuk memastikan seluruh rangkaian acara berjalan sesuai dengan rundown yang telah ditetapkan.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2875695);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66606768', 66606768, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Paket Fullboard Meeting dalam Kota Eselon I,II dan III Kebawah Kegiatan Koordinasi terkait Layanan Pengesahan dan Pendaftaran Korporasi pada Direktorat Badan Usaha Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 145140000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Tersedianya Paket fullboard meeting pejabat Eselon I & II dan Eselon III ke bawah, Termasuk Ruang Meeting, Kamar Penginapan, serta Makanan dan Minuman selama kegiatan guna mendukung kelancaran, efektivitas, dan tertibnya pelaksanaan kegiatan.', '1.Room Meeting dengan Standard Meeting facilities: (meja dan kursi untuk peserta, 1 Screen, 1 LCD Projector, sound sytem standar, memo pad, pencil, mineral water, permen, microphone flip chart, wifi). 2. Kamar tidur Single untuk es I,II dan Double untuk es III kebawah 3. Makanan dan minuman selama kegiatan', 29028000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2875696);
