INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605077', 66605077, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Paket Pertemuan Fullday Meeting dalam Kota dalam rangka Evaluasi Pelayanan Publik Direktorat Standardisasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 23660000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Pekerjaan ini merupakan kegiatan penyelenggaraan Paket Pertemuan Fullday Meeting Dalam Kota dalam rangka mendukung pelaksanaan Evaluasi Pelayanan Publik Direktorat Standardisasi Pangan Olahan. Kegiatan ini dilaksanakan melalui serangkaian pertemuan intensif dalam format fullday meeting yang diselenggarakan di dalam wilayah kota, dengan melibatkan para peserta dari unsur internal maupun pemangku kepentingan terkait dalam proses evaluasi pelayanan publik yang diselenggarakan oleh Direktorat Standardisasi Pangan Olahan. Pelaksanaan fullday meeting ini bertujuan untuk membahas secara mendalam hasil evaluasi pelayanan publik yang telah dilaksanakan oleh Direktorat Standardisasi Pangan Olahan, mencakup antara lain pengkajian capaian indikator kinerja pelayanan, identifikasi permasalahan dan hambatan dalam penyelenggaraan pelayanan publik, serta perumusan rekomendasi perbaikan yang konkret dan dapat ditindaklanjuti. Dengan format pertemuan sehari penuh, diharapkan setiap sesi pembahasan dapat berlangsung secara fokus, mendalam, dan menghasilkan kesimpulan serta rekomendasi yang komprehensif dalam rangka peningkatan kualitas pelayanan publik Direktorat Standardisasi Pangan Olahan secara berkelanjutan.', 'Lingkup pekerjaan dalam paket pertemuan fullday meeting dalam kota ini mencakup: 1. Paket Fullday Meeting Dalam Kota -Penyediaan paket pertemuan sehari penuh (fullday) yang diselenggarakan di hotel, gedung pertemuan, atau fasilitas rapat lainnya di dalam wilayah kota dalam rangka pelaksanaan evaluasi pelayanan publik Direktorat Standardisasi Pangan Olahan. -Penyelenggaraan pertemuan dilaksanakan selama minimal 8 (delapan) jam dalam satu hari kegiatan, mulai dari sesi pembukaan hingga penutupan. Kapasitas ruang rapat disesuaikan dengan jumlah peserta yang diundang dalam setiap sesi pertemuan evaluasi pelayanan publik. -Besaran biaya paket fullday meeting mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2875731);
