INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66607658', 66607658, 'analyze_legacy', 'Kab. Ogan Komering Ilir', 'kabkota', 'Badan Penanggulangan Bencana Daerah', 'Belanja Jasa petugas kebersihan Kantor/Dinas/badan', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Selatan, Ogan Komering Ilir (Kab.)', 24000000, 'March 2026', 'APBD', 1, 1, '2 orang', '~ Petugas Kebersihan Gedung Luar Kantor 1. Menyapu seluruh halaman, teras, jalan akses, dan area sekitar Gedung kantor selama 3 jam sehari 2. Membersihakan sampah, daun kering, debu, dan kotoran lainya yang berada di daerah luar Gedung. 3. Mengumpulkan dan membuang sampah ke tempat pembuangan sampah yang telah disediakan 4. Membersihakan area parker, selasar luar dan jalur pejalan kaki di lingkungan kantor 5. Menjaga kebersihan drainase atau selokan di sekitar Gedung dari sampah ringan yang mengganggu aliran 6. Menjaga kerapian dan kebersihan Lingkungan Knator agar tetap bersih dan nyaman. ~ Petugas Kebersihan Gedung Dalam Kantor 1. Melakukan pembersihan seluruh ruangan kantor, termasuk ruang kerja, ruang rapat, ruang tamu dan area pelayanan kantor selama 3 jam dalam sehari. 2. Membersihakan lantai dengan cara menyapu, mengepel dan menjaga agar lantai tetap bersih dan tidak licin 3. Membersihkan meja, kursi dan lainnya dari debu kotoran 4. Membersihkan Toilet/kamar kecil kantor, termasuk kloset dan lantai 5. Mengelola dan membuang sampah dari tempat sampah di setiap ruanganke tempat pembuangan yang telah ditentukan 6. Membersihakan area Lorong dan area umum di dalam Gedung kantor.', '~ Petugas Kebersihan Gedung Luar Kantor 1. Menyapu seluruh halaman, teras, jalan akses, dan area sekitar Gedung kantor selama 3 jam sehari 2. Membersihakan sampah, daun kering, debu, dan kotoran lainya yang berada di daerah luar Gedung. 3. Mengumpulkan dan membuang sampah ke tempat pembuangan sampah yang telah disediakan 4. Membersihakan area parker, selasar luar dan jalur pejalan kaki di lingkungan kantor 5. Menjaga kebersihan drainase atau selokan di sekitar Gedung dari sampah ringan yang mengganggu aliran 6. Menjaga kerapian dan kebersihan Lingkungan Knator agar tetap bersih dan nyaman. ~ Petugas Kebersihan Gedung Dalam Kantor 1. Melakukan pembersihan seluruh ruangan kantor, termasuk ruang kerja, ruang rapat, ruang tamu dan area pelayanan kantor selama 3 jam dalam sehari. 2. Membersihakan lantai dengan cara menyapu, mengepel dan menjaga agar lantai tetap bersih dan tidak licin 3. Membersihkan meja, kursi dan lainnya dari debu kotoran 4. Membersihkan Toilet/kamar kecil kantor, termasuk kloset dan lantai 5. Mengelola dan membuang sampah dari tempat sampah di setiap ruanganke tempat pembuangan yang telah ditentukan 6. Membersihakan area Lorong dan area umum di dalam Gedung kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2876049);
