INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605083', 66605083, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Penyusunan dan Revisi Peraturan, Standar, Pedoman dan Code of Practice di Bidang Keamanan Pangan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 175564000, 'January 2026', 'APBN - PNBP (D), APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pekerjaan ini merupakan pengadaan bahan penunjang dalam rangka pelaksanaan kegiatan Penyusunan dan Revisi Peraturan, Standar, Pedoman, dan Code of Practice di Bidang Keamanan Pangan. Kegiatan ini bertujuan untuk mendukung kelancaran proses penyusunan dan revisi regulasi melalui serangkaian rapat koordinasi, pembahasan teknis, dan konsultasi yang melibatkan berbagai pemangku kepentingan. Dalam pelaksanaannya, diperlukan penyediaan kebutuhan konsumsi berupa makan siang dan snack rapat guna menunjang kenyamanan dan efektivitas jalannya pertemuan. Selain itu, diperlukan pula layanan penjilidan dan pelaporan sebagai bentuk dokumentasi resmi dari setiap tahapan pembahasan yang telah dilakukan, sehingga seluruh proses dan hasil kegiatan dapat terdokumentasi dengan baik dan dapat dipertanggungjawabkan.', '1. Konsumsi Rapat Makan Siang: Penyediaan makan siang bagi peserta rapat dalam rangka pembahasan penyusunan dan revisi peraturan, standar, pedoman, dan code of practice di bidang keamanan pangan. Makanan disajikan dalam kondisi bersih, higienis, dan layak konsumsi, mengikuti standar keamanan pangan yang berlaku. Snack Rapat: Penyediaan makanan ringan/snack bagi peserta rapat sebagai penunjang jalannya pertemuan. Snack disajikan dalam kondisi terkemas rapi, bersih, dan memenuhi standar kelayakan konsumsi. 2. Penjilidan dan Pelaporan Penyediaan layanan penjilidan dokumen hasil rapat, draft peraturan, standar, pedoman, dan code of practice yang telah disusun maupun direvisi."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2876286);
