INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66608034', 66608034, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Jasa Konsultan Rancangan Undang-undang Badan Usaha Pada Direktorat Badan Usaha Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 500000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'ekerjaan jasa konsultan ini bertujuan untuk mendukung penyusunan Rancangan Undang-Undang tentang Badan Usaha (RUU BU) secara komprehensif, sistematis, dan sesuai dengan kebutuhan hukum nasional. Konsultan akan melakukan kajian akademik dan yuridis terhadap peraturan perundang-undangan yang berlaku, praktik penyelenggaraan badan usaha di Indonesia, serta perbandingan dengan regulasi di negara lain. Dalam pelaksanaannya, konsultan bertugas menyusun naskah akademik, merumuskan norma hukum dalam bentuk pasal-pasal RUU, serta melakukan analisis harmonisasi dan sinkronisasi dengan peraturan terkait. Selain itu, konsultan juga akan memfasilitasi kegiatan diskusi, focus group discussion (FGD), dan konsultasi publik dengan para pemangku kepentingan guna memperoleh masukan yang konstruktif. Hasil akhir dari pekerjaan ini adalah tersusunnya dokumen naskah akademik dan draft RUU Badan Usaha yang berkualitas, aplikatif, serta selaras dengan asas pembentukan peraturan perundang-undangan.', 'Pekerjaan ini mencakup beberapa ruang lingkup utama, yaitu: Kajian Awal dan Pengumpulan Data Melakukan identifikasi isu strategis, pengumpulan data primer dan sekunder, serta telaah terhadap regulasi terkait badan usaha. Penyusunan Naskah Akademik Menyusun naskah akademik yang memuat latar belakang, tujuan, sasaran pengaturan, jangkauan dan arah pengaturan, serta landasan filosofis, sosiologis, dan yuridis. Perumusan Draft RUU Menyusun pasal demi pasal RUU Badan Usaha secara sistematis sesuai dengan kaidah perundang-undangan. Harmonisasi dan Sinkronisasi Melakukan penyesuaian dengan peraturan perundang-undangan lain agar tidak terjadi tumpang tindih atau konflik norma. Konsultasi dan FGD Menyelenggarakan diskusi dengan stakeholder terkait, akademisi, dan praktisi untuk memperoleh masukan substansi. Finalisasi Dokumen Menyempurnakan naskah akademik dan draft RUU berdasarkan hasil pembahasan dan masukan, serta menyerahkan dokumen akhir. Output yang diharapkan meliputi: dokumen kajian awal, naskah akademik, draft RUU Badan Usaha, laporan kegiatan FGD/konsultasi publik, serta laporan akhir pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2878194);
