INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605073', 66605073, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Evaluasi Pelayanan Publik Direktorat Standardisasi Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 24057000, 'January 2026', 'APBN - RUPIAH MURNI (A), APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan ini merupakan pengadaan bahan penunjang dalam rangka pelaksanaan kegiatan Evaluasi Pelayanan Publik Direktorat Standardisasi Pangan Olahan. Kegiatan ini bertujuan untuk mendukung kelancaran proses evaluasi terhadap kualitas dan efektivitas pelayanan publik yang telah diselenggarakan oleh Direktorat Standardisasi Pangan Olahan, melalui serangkaian rapat pembahasan dan kajian yang melibatkan berbagai pemangku kepentingan, baik dari unsur internal maupun pihak terkait lainnya. Dalam pelaksanaannya, diperlukan penyediaan kebutuhan konsumsi berupa makan rapat biasa dan snack rapat guna menunjang kenyamanan dan efektivitas jalannya pembahasan selama kegiatan evaluasi pelayanan publik berlangsung. Penyediaan konsumsi ini merupakan bagian dari belanja bahan yang diperlukan untuk memastikan seluruh rangkaian rapat evaluasi dapat terlaksana dengan baik, kondusif, dan menghasilkan rekomendasi perbaikan pelayanan publik yang konkret dan dapat ditindaklanjuti oleh Direktorat Standardisasi Pangan Olahan.', 'Lingkup pekerjaan dalam paket belanja bahan ini mencakup: 1. Makan Rapat Biasa -Penyediaan makan rapat biasa bagi peserta dalam rangka pelaksanaan kegiatan evaluasi pelayanan publik Direktorat Standardisasi Pangan Olahan. -Besaran biaya makan rapat biasa mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 2. Snack Rapat -Penyediaan makanan ringan/snack bagi peserta rapat sebagai penunjang kelancaran jalannya diskusi dan pembahasan dalam kegiatan evaluasi pelayanan publik Direktorat Standardisasi Pangan Olahan. -Besaran biaya snack rapat mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2878823);
