INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66606292', 66606292, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Rekomendasi Kebijakan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 94460000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Melakukan pemutakhiran data secara berkala untuk data kesehatan. Koordinasi dengan berbagai pihak terkait kebutuhan data kesehatan dan aspek lain yang mendukung kesehatan dan gizi masyarakat untuk melakukan analisis, proyeksi dan evaluasi. Merumuskan rekomendasi berbasis data untuk penguatan tata kelola, efektivitas pelaksanaan, dan keberlanjutan program khususnya peningkatan status kesehatan dan gizi masyarakat. Memberikan pelatihan analisis data.', 'Pendidikan minimal S2 di bidang Statistik/ Aktuaria/ Matematika /Ilmu Ekonomi/ Kesehatan Masyarakat/ Statistik/ Ilmu Komputer/ Data Science/ Teknik Industri. Dibuktikan dengan Ijazah. Memiliki pengalaman kerja minimal 5 tahun dalam analisis data/ pengembangan dashboard/ pengelolaan sistem manajemen data bidang kesehatan/ sosial/ pendidikan/ kemiskinan/ pemberdayaan masyarakat. Dibuktikan dengan surat keterangan kerja/ surat referensi/ kontrak kerja/ sertifikat. Menguasai tools visualisasi data seperti Tableau/ Google Data Studio/ Power BI. Dibuktikan dengan hasil visualisasi data yang pernah dikerjakan/ hasil analisis data/ hasil publikasi/ hasil artikel. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. Memiliki pekerjaan sejenis terkait bidang kesehatan/ data analis/ manajemen/ data researcher yang dibuktikan dengan surat keterangan kerja/ surat referensi/ kontrak kerja/ sertifikat. Mempunyai status valid keterangan wajib pajak berdasarkan hasil konfirmasi status wajib pajak. Diutamakan Tenaga Pendukung dalam negeri yang dibuktikan dengan identitas kewarganegaraan Indonesia sebagai Kartu Tanda Penduduk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2879109);
