INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66605084', 66605084, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Evaluasi Kualitas Kebijakan / Standar Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 50119000, 'January 2026', 'APBN - PNBP (D), APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pekerjaan ini merupakan pengadaan bahan penunjang dalam rangka pelaksanaan kegiatan Evaluasi Kualitas Kebijakan/Standar Pangan Olahan. Kegiatan ini bertujuan untuk mendukung kelancaran proses evaluasi terhadap kebijakan dan standar yang telah ditetapkan di bidang pangan olahan, melalui serangkaian rapat pembahasan dan kajian teknis yang melibatkan berbagai pemangku kepentingan, baik dari unsur internal maupun eksternal yang terkait.Dalam pelaksanaannya, diperlukan penyediaan kebutuhan konsumsi berupa makan siang dan snack rapat guna menunjang kenyamanan dan efektivitas jalannya pembahasan selama kegiatan evaluasi berlangsung. Selain itu, diperlukan pula layanan pencetakan dan pelaporan sebagai bentuk dokumentasi resmi dari seluruh proses dan hasil evaluasi yang telah dilakukan, sehingga setiap tahapan kegiatan dapat terdokumentasi dengan baik, tertata rapi, dan dapat dipertanggungjawabkan sebagai arsip resmi kegiatan evaluasi kualitas kebijakan/standar pangan olahan.', 'Lingkup pekerjaan dalam paket belanja bahan ini mencakup: 1. Makan Siang Penyediaan makan siang bagi peserta rapat dalam rangka pelaksanaan kegiatan evaluasi kualitas kebijakan/standar pangan olahan. Besaran biaya makan siang mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 2. Snack Rapat Penyediaan makanan ringan/snack bagi peserta rapat sebagai penunjang kelancaran jalannya diskusi dan pembahasan teknis dalam kegiatan evaluasi kualitas kebijakan/standar pangan olahan. Besaran biaya snack rapat mengacu pada Standar Biaya Masukan (SBM) yang ditetapkan oleh Kementerian Keuangan Republik Indonesia yang berlaku pada tahun anggaran berjalan. 3. Pencetakan Penyediaan pencetakan dokumen yang diperlukan dalam rangka pelaksanaan kegiatan evaluasi kualitas kebijakan/standar pangan olahan. Pencetakan meliputi hasil dari survei yang dilaksanakan 4. Pelaporan Pelaporan mencakup seluruh tahapan kegiatan evaluasi, mulai dari persiapan, pelaksanaan, hingga hasil dan rekomendasi yang dihasilkan dari proses evaluasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2879811);
